diff --git a/src/components/SubscriptionModal.tsx b/src/components/SubscriptionModal.tsx
--- a/src/components/SubscriptionModal.tsx
+++ b/src/components/SubscriptionModal.tsx
@@ -1,15 +1,24 @@
 import React from 'react';
 import { Prompt } from './Prompt';
-import { getSubscriptionMessage } from '../helpers/subscription';
+import { getSubscriptionMessage, SubscriptionPlatform, SubscriptionManager } from '../helpers/subscription';

-interface Props {
-    subscriptionManager: any;
-    platform: string;
+interface SubscriptionModalProps {
+    subscriptionManager: SubscriptionManager;
+    platform: SubscriptionPlatform;
     onClose: () => void;
 }

-export const SubscriptionModal = ({ subscriptionManager, platform, onClose }: Props) => {
-    const message = getSubscriptionMessage(subscriptionManager, platform);
+export const SubscriptionModal = ({ subscriptionManager, platform, onClose }: SubscriptionModalProps) => {
+    const { title, body, footer } = getSubscriptionMessage(subscriptionManager, platform);

-    return <Prompt title="Subscription Warning" message={message} onClose={onClose} />;
+    return (
+        <Prompt 
+            title={title} 
+            onClose={onClose}
+        >
+            <div className="subscription-modal-body">
+                {body}
+            </div>
+            {footer && <div className="subscription-modal-footer">{footer}</div>}
+        </Prompt>
+    );
 };
diff --git a/src/helpers/subscription.ts b/src/helpers/subscription.ts
--- a/src/helpers/subscription.ts
+++ b/src/helpers/subscription.ts
@@ -1,11 +1,33 @@
-export const getSubscriptionMessage = (subscriptionManager: any, platform: string) => {
-    if (platform === 'ios') {
-        return 'Your subscription is managed by Apple. Please go to the App Store to manage your subscription: ' + subscriptionManager.getAppleUrl();
-    }
-    if (platform === 'android') {
-        return 'Your subscription is managed by Google. Please go to the Play Store to manage your subscription: ' + subscriptionManager.getGoogleUrl();
-    }
-    return 'Your subscription is managed by Proton. Please go to the dashboard to manage your subscription.';
+import { ReactNode } from 'react';
+
+export enum SubscriptionPlatform {
+    IOS = 'ios',
+    ANDROID = 'android',
+    WEB = 'web'
+}
+
+export interface SubscriptionManager {
+    getAppleUrl: () => string;
+    getGoogleUrl: () => string;
+}
+
+export interface SubscriptionMessage {
+    title: string;
+    body: ReactNode;
+    footer?: ReactNode;
+}
+
+export const getSubscriptionMessage = (subscriptionManager: SubscriptionManager, platform: SubscriptionPlatform): SubscriptionMessage => {
+    const messages: Record<SubscriptionPlatform, SubscriptionMessage> = {
+        [SubscriptionPlatform.IOS]: {
+            title: 'Manage iOS Subscription',
+            body: 'Your subscription is managed by Apple. Please use the App Store to manage your billing and plan.',
+            footer: subscriptionManager.getAppleUrl()
+        },
+        [SubscriptionPlatform.ANDROID]: {
+            title: 'Manage Android Subscription',
+            body: 'Your subscription is managed by Google. Please use the Play Store to manage your billing and plan.',
+            footer: subscriptionManager.getGoogleUrl()
+        },
+        [SubscriptionPlatform.WEB]: {
+            title: 'Manage Subscription',
+            body: 'Your subscription is managed by Proton. You can manage your plan directly from your account settings.'
+        }
+    };
+
+    return messages[platform] || messages[SubscriptionPlatform.WEB];
 };
